SELECT 
FROM cms_kb_document

    del_flag = 0
    AND category_id = #{categoryId}
    AND title LIKE CONCAT('%', #{title}, '%')
    AND doc_type = #{docType}
    AND status = #{status}
    AND is_required = #{isRequired}

